def main():
    import sys
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    q = int(data[1])
    m = int(data[2])

    arr = list(map(int, data[3:3+n]))

    queries = []
    idx = 3 + n
    for i in range(q):
        if idx + 2 >= len(data):
            break
        t = int(data[idx])
        l = int(data[idx+1])
        r = int(data[idx+2])
        queries.append((t, l, r))
        idx += 3

    b_indices = []
    for i in range(m):
        if idx + i >= len(data):
            break
        b_indices.append(int(data[idx+i]))

    result = []
    for bi in b_indices:
        pos = bi
        for t, l, r in reversed(queries):
            l0 = l - 1
            r0 = r - 1
            if t == 1:
                if l0 <= pos <= r0:
                    if pos == r0:
                        pos = l0
                    else:
                        pos = pos + 1
            else:
                if l0 <= pos <= r0:
                    pos = l0 + r0 - pos
        result.append(str(arr[pos]))

    print(' '.join(result))

if __name__ == "__main__":
    main()
